SQL_DOC.P_SQL:
SELECT '$G_RS.BUYER$' AS BUYER, '$G_RS.DOC_TYPE$' AS DOC_TYPE, '$G_RS.KEY_NO$' AS KEY_NO, '$G_RS.KEY_SEQ$' AS KEY_SEQ, '$G_RS.DATA01$' AS DATA01, '$G_RS.DATA02$' AS DATA02, '$G_RS.DATA03$' AS DATA03, '$G_RS.DATA04$' AS DATA04, '$G_RS.DATA05$' AS DATA05
FROM DUAL
BEGIN IF '$G_RS.DOC_TYPE$' = 'PO' THEN UPDATE MRO_PO_REQ SET
MRO_SEND = 'Y' , MRO_SEND_DT = SYSDATE
WHERE PO_REQ_NO = '$G_RS.KEY_NO$' AND GD_CD_MRO = '$G_RS.KEY_SEQ$';
ELSIF '$G_RS.DOC_TYPE$' = 'INV' THEN UPDATE MRO_PO_IPGO SET IF_FLAG = 'Y', IF_DATE = SYSDATE
WHERE PO_REQ_NO = '$G_RS.KEY_NO$' AND GD_CD_MRO = '$G_RS.KEY_SEQ$' AND IP_DT = '$G_RS.DATA02$' AND STATUS = '$G_RS.DATA03$'; END IF; END;
BEGIN IF '$G_RS.DOC_TYPE$' = 'PO' THEN UPDATE MRO_PO_REQ SET MRO_SEND = 'E' , MRO_SEND_DT = SYSDATE
WHERE PO_REQ_NO = '$G_RS.KEY_NO$' AND GD_CD_MRO = '$G_RS.KEY_SEQ$';
ELSIF '$G_RS.DOC_TYPE$' = 'INV' THEN UPDATE MRO_PO_IPGO SET IF_FLAG = 'E', IF_DATE = SYSDATE
WHERE PO_REQ_NO = '$G_RS.KEY_NO$' AND GD_CD_MRO = '$G_RS.KEY_SEQ$' AND IP_DT = '$G_RS.DATA02$' AND STATUS = '$G_RS.DATA03$'; END IF; END;
